import{_ as r,a0 as i,w as u,s,I as o,x as e,a1 as n,A as p,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"不是程序員？那就找到自己的定位 | LCTT x X-CMD","titleTemplate":false,"description":"不是程序員？那就找到自己的定位 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不是程序員？那就找到自己的定位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不是程序員？那就找到自己的定位 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210218 Not an engineer- Find out where you belong","title":"不是程序員？那就找到自己的定位","tag":"202105","desc":""},"relativePath":"202105/20210218 Not an engineer- Find out where you belong.md","filePath":"[post].md"}'),d={name:"202105/20210218 Not an engineer- Find out where you belong.md"};function m(b,t,f,k,T,g){const l=i("Link");return u(),s("div",null,[t[23]||(t[23]=o("h1",{id:"不是程序員-那就找到自己的定位",tabindex:"-1"},[e("不是程序員？那就找到自己的定位 "),o("a",{class:"header-anchor",href:"#不是程序員-那就找到自己的定位","aria-label":"Permalink to “不是程序員？那就找到自己的定位”"},"​")],-1)),t[24]||(t[24]=o("blockquote",null,[o("p",null,"無論你是已經工作了幾十年的還是剛開始從業的非工程型技術人，此建議都可以幫助你確定你的位置歸屬。")],-1)),t[25]||(t[25]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/31/192647jl354n1jezx1ea1c.jpg",alt:""})],-1)),o("p",null,[t[2]||(t[2]=e("在 ",-1)),n(l,{href:"https://linux.cn/article-13168-1.html"},{default:p(()=>[...t[0]||(t[0]=[e("本系列第一篇文章",-1)])]),_:1}),t[3]||(t[3]=e(" 中 ，我解釋了將人員和角色分為“技術”或“非技術”類別的問題。在 ",-1)),n(l,{href:"https://linux.cn/article-13178-1.html"},{default:p(()=>[...t[1]||(t[1]=[e("第二篇文章",-1)])]),_:1}),t[4]||(t[4]=e(" 中，我為不寫代碼的人分享了一些技術崗位角色。這一次，我將把這次探索總結為——“技術或非技術意味着什麼”，並提供一些能夠在職業發展上幫到你的建議。",-1))]),t[26]||(t[26]=a('<p>無論你是已經從事技術工作數十年，或是剛剛起步，還是正在尋求職業變更，請考慮本文中來自非技術人員但在技術角色方面取得成功的人士的建議。</p><blockquote><p>“不要把你的工作和身份捆綁起來 —— 把它們分開。”</p><p>—— Adam Gordon Bell，Earthly Technologies 開發者關係部</p></blockquote><p>轉換角色，並不意味着你的技能會消失且你不再具有價值。如果你擔任了新角色，則需要專注於該角色的關鍵技能。培養技能是需要時間的。花點時間，找出新職位的重要技能。</p><p>如果你管理工程師們，請鼓勵他們提升技術技能的同時發展非工程技能，這些技能往往能比編程能力和技術技能對職業發展和成功產生更顯著的變化。</p><h3 id="做你自己" tabindex="-1">做你自己 <a class="header-anchor" href="#做你自己" aria-label="Permalink to “做你自己”">​</a></h3><blockquote><p>“不要讓其他人定義你是技術人員還是非技術人員。什麼是技術人員，什麼不是技術人員，以及這是否重要，是人們必須自己搞清楚的事情。”</p><p>—— Adam Gordon Bell</p></blockquote><blockquote><p>“永遠不要用‘我不是技術人員’為開頭進行對話。因為很可能讓對方產生‘這點我需要提醒你’的想法，這在面試的時候可從來不會留下好印象，而且還有可能會讓人覺得你對自己技能缺乏信心。”</p><p>—— Mary Thengvall，Camunda 開發者關係總監</p></blockquote><p>避免刻板成見；不是所有的工程師都喜歡《星球大戰》或《星際迷航》。不是所有工程師都穿連帽衞衣。工程師也可以和別人交流。</p><blockquote><p>“單單就你的行為舉止，旁人就有很多關於技術或非技術方面的看法。在辦公室工作的時候，我會穿裙子，因為只有這樣我才能舒服一點。”</p><p>—— Shailvi Wakhlu，Strava 高級數據總監</p></blockquote><h3 id="瞭解你的價值" tabindex="-1">瞭解你的價值 <a class="header-anchor" href="#瞭解你的價值" aria-label="Permalink to “瞭解你的價值”">​</a></h3>',10)),o("p",null,[t[6]||(t[6]=e("正如我在第一篇文章中討論的那樣，被打上“非技術”的標籤會導致 ",-1)),n(l,{href:"https://opensource.com/business/15/9/tips-avoiding-impostor-syndrome"},{default:p(()=>[...t[5]||(t[5]=[e("冒充者綜合症",-1)])]),_:1}),t[7]||(t[7]=e("。承認自己的價值，不要在自己身上貼上“非技術”標籤，因為它會限制你的收入潛力和職業發展。",-1))]),t[27]||(t[27]=a('<blockquote><p>“人們之所以把我重新包裝成其他東西，是因為他們認為我和工程師的刻板印象不一樣。我很高興我沒有聽這些人的話，因為他們本質上是在告訴我，在我擁有的技能之外，去找一份低薪的工作。”</p><p>—— Shailvi Wakhlu</p></blockquote><blockquote><p>“年輕的或者女性技術人，特別是剛接觸技術的女性，更容易患上冒名綜合症，認為自己技術不夠好。比如，‘哦，我只會前端。’，什​​麼叫你<em>只會</em>前端？前端也很難的好吧。”</p><p>—— Liz Harris</p></blockquote><h3 id="尋找那些可以提升價值並幫到人們的地方" tabindex="-1">尋找那些可以提升價值並幫到人們的地方 <a class="header-anchor" href="#尋找那些可以提升價值並幫到人們的地方" aria-label="Permalink to “尋找那些可以提升價值並幫到人們的地方”">​</a></h3><p>你不需要創建 PR 就可以參與開源。</p><blockquote><p>“當有人想為開源項目做點貢獻時，我總是對他説，‘不要想着，得是一個提交才行、得提一個 PR 才可以。’這就好像，‘不行。怎麼才能為那個項目貢獻點價值呢？’ 如果你沒時間提交 PR，那你是不是提個議題並把要點寫下來？”</p><p>—— Eddie Jaoude，Jaoude Studios 開源程序員</p></blockquote><h3 id="思維的多樣性有助於事業成功" tabindex="-1">思維的多樣性有助於事業成功 <a class="header-anchor" href="#思維的多樣性有助於事業成功" aria-label="Permalink to “思維的多樣性有助於事業成功”">​</a></h3><p>看看所有角色和人員的價值和貢獻。不要根據頭銜將人歸到同能力的一組。</p><blockquote><p>“要認識到，所有人（包括自己在內），在任何時候，以及事情全貌的重要性。創造力這個事兒不應該由自我驅動。要知道，對於你所做的事情，你可以做的更好，也可以做的更糟。不要害怕尋求幫助，知道到我們在一起。”</p><p>—— Therese Eberhard，電影/廣告和視頻場景畫師</p></blockquote><blockquote><p>“在我參加過的黑客馬拉松中，我們都是技術人員，組建了一支四五個硬核程序員組成的強大團隊，但我們輸了。我不騙你，我們輸了。在新冠疫情之前，我贏了前六次的黑客馬拉松，而且當時團隊中一半的人屬於其他領域的專家。在我們贏過的比賽中，大多數人會認為團隊一半人是非技術的，儘管我不喜歡這個術語，因為這像是給團隊/項目貼金。我們之所以獲勝，是因為我們對所構建的東西有很多不同的看法。”</p><p>—— Eddie Jaoude</p></blockquote><blockquote><p>“我們越能擺脱‘技術/非技術’、‘開發人員/非開發人員’的標籤，並理解到一個連續統一的整體存在，我們就越能全力以赴地僱用到合適的人來做這項工作，只要不被你需要‘技術團隊’的假設所困擾。”</p><p>—— Mary Thengvall</p></blockquote><p>我們的社區和團隊越多樣化，它們的包容性就越大。</p><blockquote><p>“老實説，無論是從社區角度還是從產品角度，我認為，總的來説，最重要的事情都是，我們應該確保我們建立的是一個包容性的社區，這不僅是為了我們的產品，也不僅是為了我們正在使用的技術，還為了整個人類社會，我想……我敢打賭，如果我們做到了這一點，那麼作為人類，我們就比過去更進步了。”</p><p>—— Leon Stigter，Lightbend 高級產品經理</p></blockquote><p>如果你以非程序員的技術身份工作，你會給那些認為自己“非技術”的人（或被他人認為是“非技術”的人）提供什麼建議？ 在評論中分享你的見解。</p><hr>',14)),o("p",null,[t[9]||(t[9]=e("via: ",-1)),n(l,{href:"https://opensource.com/article/21/2/advice-non-technical"},{default:p(()=>[...t[8]||(t[8]=[e("https://opensource.com/article/21/2/advice-non-technical",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=e("作者：",-1)),n(l,{href:"https://opensource.com/users/dawnparzych"},{default:p(()=>[...t[10]||(t[10]=[e("Dawn Parzych",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),n(l,{href:"https://github.com/max27149"},{default:p(()=>[...t[12]||(t[12]=[e("max27149",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[20]||(t[20]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const C=r(d,[["render",m]]);export{q as __pageData,C as default};
